INSERT INTO "courses" ("id", "title", "summary", "description", "category", "icon", "status", "sort_order") VALUES ('22222222-2222-4222-8222-222222222208', 'Get to Know Acme Academy', 'Learn more about our mission, values, and culture', 'Start here. This course introduces who we are, what we stand for, and how we work together. Take your time with each lesson — understanding our culture will make everything else easier.', 'Company', 'building', 'published', 1) ON CONFLICT ("id") DO NOTHING;--> statement-breakpoint
INSERT INTO "courses" ("id", "title", "summary", "description", "category", "icon", "status", "sort_order") VALUES ('22222222-2222-4222-8222-222222222209', 'Systems & Tools', 'Set up your workspace and access essential tools', 'Get your accounts, devices, and everyday tools set up securely so you can be productive from day one. If any access request is stuck for more than a day, contact the IT help desk.', 'Workspace', 'laptop', 'published', 2) ON CONFLICT ("id") DO NOTHING;--> statement-breakpoint
INSERT INTO "lessons" ("id", "course_id", "title", "description", "resource_url", "duration_minutes", "priority", "required", "sort_order") VALUES ('33333333-3333-4333-8333-333333308001', '22222222-2222-4222-8222-222222222208', 'Our mission and values', 'Why we exist, the values that guide our decisions, and how they show up in everyday work.', NULL, 30, 'high', true, 1) ON CONFLICT ("id") DO NOTHING;--> statement-breakpoint
INSERT INTO "lessons" ("id", "course_id", "title", "description", "resource_url", "duration_minutes", "priority", "required", "sort_order") VALUES ('33333333-3333-4333-8333-333333308002', '22222222-2222-4222-8222-222222222208', 'Read the company handbook', 'Familiarize yourself with our policies, benefits overview, and code of conduct.', NULL, 120, 'high', true, 2) ON CONFLICT ("id") DO NOTHING;--> statement-breakpoint
INSERT INTO "lessons" ("id", "course_id", "title", "description", "resource_url", "duration_minutes", "priority", "required", "sort_order") VALUES ('33333333-3333-4333-8333-333333308003', '22222222-2222-4222-8222-222222222208', 'Org chart and leadership team', 'Learn how teams are organized, who leads each area, and where your role fits in.', NULL, 20, 'medium', true, 3) ON CONFLICT ("id") DO NOTHING;--> statement-breakpoint
INSERT INTO "lessons" ("id", "course_id", "title", "description", "resource_url", "duration_minutes", "priority", "required", "sort_order") VALUES ('33333333-3333-4333-8333-333333308004', '22222222-2222-4222-8222-222222222208', 'How we communicate', 'Our norms for chat, email, and meetings — response times, async-first habits, and meeting etiquette.', NULL, 20, 'medium', true, 4) ON CONFLICT ("id") DO NOTHING;--> statement-breakpoint
INSERT INTO "lessons" ("id", "course_id", "title", "description", "resource_url", "duration_minutes", "priority", "required", "sort_order") VALUES ('33333333-3333-4333-8333-333333308005', '22222222-2222-4222-8222-222222222208', 'Schedule coffee chats with your team', 'Book short intro calls with teammates and key partners to start building relationships early.', NULL, 60, 'low', false, 5) ON CONFLICT ("id") DO NOTHING;--> statement-breakpoint
INSERT INTO "lessons" ("id", "course_id", "title", "description", "resource_url", "duration_minutes", "priority", "required", "sort_order") VALUES ('33333333-3333-4333-8333-333333309001', '22222222-2222-4222-8222-222222222209', 'Set up your laptop', 'Sign in, install system updates, and confirm disk encryption and screen lock are turned on.', NULL, 45, 'high', true, 1) ON CONFLICT ("id") DO NOTHING;--> statement-breakpoint
INSERT INTO "lessons" ("id", "course_id", "title", "description", "resource_url", "duration_minutes", "priority", "required", "sort_order") VALUES ('33333333-3333-4333-8333-333333309002', '22222222-2222-4222-8222-222222222209', 'Turn on multi-factor authentication', 'Enable MFA on your work accounts and store your recovery codes in the company password manager.', 'https://www.cisa.gov/MFA', 15, 'high', true, 2) ON CONFLICT ("id") DO NOTHING;--> statement-breakpoint
INSERT INTO "lessons" ("id", "course_id", "title", "description", "resource_url", "duration_minutes", "priority", "required", "sort_order") VALUES ('33333333-3333-4333-8333-333333309003', '22222222-2222-4222-8222-222222222209', 'Email, calendar, and chat', 'Set up your email signature, share your calendar working hours, and join your team’s chat channels.', NULL, 30, 'high', true, 3) ON CONFLICT ("id") DO NOTHING;--> statement-breakpoint
INSERT INTO "lessons" ("id", "course_id", "title", "description", "resource_url", "duration_minutes", "priority", "required", "sort_order") VALUES ('33333333-3333-4333-8333-333333309004', '22222222-2222-4222-8222-222222222209', 'Access the HR system (HRIS)', 'Log in to the HR system, check your personal details, and add emergency contacts and direct deposit.', NULL, 20, 'medium', true, 4) ON CONFLICT ("id") DO NOTHING;--> statement-breakpoint
INSERT INTO "lessons" ("id", "course_id", "title", "description", "resource_url", "duration_minutes", "priority", "required", "sort_order") VALUES ('33333333-3333-4333-8333-333333309005', '22222222-2222-4222-8222-222222222209', 'Request access to team tools', 'Ask your manager which shared drives, project boards, and apps your role needs, then submit access requests.', NULL, 20, 'medium', true, 5) ON CONFLICT ("id") DO NOTHING;--> statement-breakpoint
INSERT INTO "lessons" ("id", "course_id", "title", "description", "resource_url", "duration_minutes", "priority", "required", "sort_order") VALUES ('33333333-3333-4333-8333-333333309006', '22222222-2222-4222-8222-222222222209', 'Personalize your workspace', 'Add a profile photo, set your notification preferences, and bookmark the tools you’ll use daily.', NULL, 15, 'low', false, 6) ON CONFLICT ("id") DO NOTHING;
